<script setup lang="ts">
import {computed,ref,onBeforeUnmount,onMounted} from 'vue'
import {ListChecks} from 'lucide-vue-next'
import {DialogRoot,DialogPortal,DialogOverlay,DialogContent,DialogTitle,DialogDescription,DialogClose,ToggleGroupRoot,ToggleGroupItem} from 'reka-ui'
import WorkbenchCheckbox from './WorkbenchCheckbox.vue'
import WorkbenchProgress from './WorkbenchProgress.vue'
import WorkbenchSelect from './WorkbenchSelect.vue'
import StorageDiagnostics from './StorageDiagnostics.vue'
import {chooseFolder} from '../lib/storage'
import {runBatch} from '../core/batch'
import {loadBatch,saveBatch,clearBatch,withBatchLock,batchStorageKey,reconcileBatchCleanup,clearBatchCheckpoints} from '../core/batch-journal'
import {loadResumeSession,resumePermission,authorizeResumeFolder} from '../core/resume'
import type {BatchJournal} from '../core/batch-journal'
import type {BatchResult} from '../core/batch'
import type {MediaJob} from '../core/workspace'
import {humanBytes} from '../lib/format'
const props=defineProps<{jobs:MediaJob[];labels:Record<string,string>;states:Record<string,string>}>()
const emit=defineEmits<{retry:[MediaJob];clear:[]}>()
const filter=ref('all'),search=ref(''),group=ref(false)
const batchPriority=ref<'background'|'normal'|'high'>('background')
const batchFiles=ref<File[]>([]),batchMode=ref<'split'|'frames'>('split'),batchSize=ref(4),batchInterval=ref(30),batchRows=ref<BatchResult[]>([]),batchBusy=ref(false),batchError=ref('')
let batchController:AbortController|null=null
const recoveredBatch=ref<BatchJournal|null>(loadBatch())
let lastPersist=0
const permissionRows=ref<Record<string,string>>({})
async function refreshPermissions(){for(const id of recoveredBatch.value?.sessions??[]){if(!id)continue;try{permissionRows.value[id]=await resumePermission(id)}catch{permissionRows.value[id]='unknown'}}}
async function reauthorize(id:string){try{const session=await loadResumeSession(id);if(!session)throw Error('检查点已不存在');await authorizeResumeFolder(session.folder);await refreshPermissions()}catch(e){batchError.value=String(e)}}
const confirmCleanup=ref(false)
async function forgetBatchCheckpoints(){confirmCleanup.value=false;try{await withBatchLock(async()=>{const current=loadBatch();if(!current||current.id!==recoveredBatch.value?.id)throw Error('批次已在其他标签页改变，请刷新');await clearBatchCheckpoints(current);recoveredBatch.value=null;batchRows.value=[];permissionRows.value={}})}catch(e){batchError.value=String(e)}}
function syncBatch(e:StorageEvent){if(e.key!==batchStorageKey||batchBusy.value)return;recoveredBatch.value=loadBatch();batchRows.value=recoveredBatch.value?.rows??[];void refreshPermissions()}
async function reconcileCleanup(){try{await withBatchLock(async()=>{if(await reconcileBatchCleanup()){recoveredBatch.value=null;batchRows.value=[];permissionRows.value={}}})}catch(e){if(!/另一标签页/.test(String(e)))batchError.value=String(e)}}
onMounted(()=>{window.addEventListener('storage',syncBatch);void reconcileCleanup().then(refreshPermissions)})
function persistBatch(j:BatchJournal,force=false){if(!force&&Date.now()-lastPersist<500)return;lastPersist=Date.now();try{j.updatedAt=Date.now();saveBatch({...j,rows:j.rows.map(r=>({...r}))})}catch(e){batchError.value='批量历史持久化失败';if(force)throw e}}
async function discardBatch(){try{await withBatchLock(async()=>{clearBatch();recoveredBatch.value=null;batchRows.value=[]})}catch(e){batchError.value=String(e)}}
if(recoveredBatch.value){batchRows.value=recoveredBatch.value.rows;batchMode.value=recoveredBatch.value.settings.mode;batchSize.value=recoveredBatch.value.settings.maxBytes/1e9;batchInterval.value=recoveredBatch.value.settings.interval;batchPriority.value=recoveredBatch.value.settings.priority??'background'}
function selectBatch(e:Event){const el=e.target as HTMLInputElement;batchFiles.value=Array.from(el.files??[]).slice(0,50);el.value='';if(!recoveredBatch.value)batchRows.value=[]}
async function startBatch(restore=false){if(batchBusy.value||!batchFiles.value.length)return;batchBusy.value=true;batchError.value='';const ctl=new AbortController();batchController=ctl;try{const files=[...batchFiles.value];const prior=restore?recoveredBatch.value:null;if(restore&&(!prior||!prior.sessions?.some(Boolean)))throw Error('该批次没有可恢复的目录检查点');if(prior&&(files.length!==prior.files.length||files.some((f,i)=>f.name!==prior.files[i].name||f.size!==prior.files[i].bytes||f.lastModified!==prior.files[i].lastModified)))throw Error('请按原顺序重新选择完整批次源文件');const settings=prior?.settings??{mode:batchMode.value,maxBytes:Math.floor(batchSize.value*1e9),interval:batchInterval.value,priority:batchPriority.value};const folder=await chooseFolder();await withBatchLock(async()=>{if(await reconcileBatchCleanup()&&prior)throw Error('原批次检查点已清理，请新建任务');const latest=loadBatch();if(prior&&latest?.id!==prior.id)throw Error('批次已在另一个标签页变化');if(prior&&(!latest||files.length!==latest.files.length||files.some((f,i)=>f.name!==latest.files[i].name||f.size!==latest.files[i].bytes||f.lastModified!==latest.files[i].lastModified)))throw Error('原批次源文件已变化');const sessions=prior?[...(latest?.sessions??[])]:[];if(prior&&!sessions.some(Boolean))throw Error('该批次没有可恢复检查点');batchRows.value=files.map(f=>({name:f.name,status:'waiting',detail:'等待处理'}));const journal:BatchJournal={id:prior?.id??crypto.randomUUID(),settings:prior&&latest?latest.settings:settings,files:files.map(f=>({name:f.name,bytes:f.size,lastModified:f.lastModified})),rows:batchRows.value,updatedAt:Date.now(),sessions};recoveredBatch.value=journal;persistBatch(journal,true);await runBatch(files,folder,journal.settings,ctl.signal,(i,row)=>{batchRows.value[i]=row;persistBatch(journal,row.status!=='running')},sessions,(i,id)=>{sessions[i]=id;persistBatch(journal,true)});persistBatch(journal,true)});await refreshPermissions()}catch(e){batchError.value=e instanceof Error?e.message:String(e)}finally{batchBusy.value=false;batchController=null}}
onBeforeUnmount(()=>{batchController?.abort();window.removeEventListener('storage',syncBatch)})
const active=(j:MediaJob)=>['queued','running','canceling'].includes(j.status)
const failed=(j:MediaJob)=>['failed','canceled','interrupted','partial'].includes(j.status)
const filtered=computed(()=>props.jobs.filter(j=>(filter.value==='all'||filter.value==='active'&&active(j)||filter.value==='failed'&&failed(j)||filter.value==='completed'&&j.status==='completed')&&j.asset.name.toLowerCase().includes(search.value.toLowerCase())))
const groups=computed(()=>{const map=new Map<string,MediaJob[]>();for(const j of filtered.value){const key=group.value?j.asset.name:'全部任务';const items=map.get(key)??[];items.push(j);map.set(key,items)}return Array.from(map.entries())})
function exportReport(){const url=URL.createObjectURL(new Blob([JSON.stringify(filtered.value,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='frameslice-job-history.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),30000)}
</script>
<template><div class="content fs-job-center"><DialogRoot v-model:open="confirmCleanup"><DialogPortal><DialogOverlay class="fs-dialog-overlay"/><DialogContent class="fs-dialog-content"><DialogTitle>删除批次检查点？</DialogTitle><DialogDescription>仅删除续作元数据和目录引用，保留磁盘文件。删除后无法再使用原检查点恢复。</DialogDescription><div class="fs-dialog-actions"><DialogClose as-child><button class="secondary-button">取消</button></DialogClose><button class="secondary-button fs-danger" @click="forgetBatchCheckpoints">确认删除</button></div></DialogContent></DialogPortal></DialogRoot><div class="page-head"><h1>任务中心</h1></div>
 <ToggleGroupRoot class="fs-center-metrics fs-segmented" type="single" :model-value="filter" aria-label="任务状态筛选" @update:model-value="value=>{if(typeof value==='string'&&value)filter=value}"><ToggleGroupItem class="secondary-button" value="all">全部 {{jobs.length}}</ToggleGroupItem><ToggleGroupItem class="secondary-button" value="active">进行中 {{jobs.filter(active).length}}</ToggleGroupItem><ToggleGroupItem class="secondary-button" value="failed">需处理 {{jobs.filter(failed).length}}</ToggleGroupItem><ToggleGroupItem class="secondary-button" value="completed">完成 {{jobs.filter(j=>j.status==='completed').length}}</ToggleGroupItem></ToggleGroupRoot>
 <div class="fs-center-toolbar"><input v-model="search" placeholder="搜索媒体名称" aria-label="搜索任务"/><WorkbenchCheckbox v-model="group">按媒体分组</WorkbenchCheckbox><button class="secondary-button" @click="exportReport">导出历史 JSON</button><button class="secondary-button" @click="emit('clear')">清除结束记录</button></div>
 <section class="fs-jobs-list" aria-label="任务列表"> <div v-if="!filtered.length" class="fs-jobs-empty"><ListChecks :size="24"/><strong>{{jobs.length?'暂无匹配任务':'暂无任务'}}</strong><small>{{jobs.length?'调整筛选条件或搜索词后再试':'处理媒体后，任务记录将在这里显示。'}}</small><button v-if="jobs.length" type="button" class="secondary-button" @click="filter='all';search=''">重置筛选</button></div>
 <section v-for="[name,items] in groups" :key="name" class="fs-analysis fs-job-group"><h3>{{name}} <small>{{items.length}} 项</small></h3><article v-for="j in items" :key="j.id" class="fs-center-job"><div><strong>{{labels[j.type]}} <span class="fs-job-status" :data-status="j.status">{{states[j.status]}}</span></strong><small>{{j.asset.name}} · {{humanBytes(j.asset.bytes)}}</small><small>{{j.label}} · {{new Date(j.createdAt).toLocaleString()}}</small><small v-if="j.checkpoint">已确认 {{j.checkpoint.count}} 个输出 · {{j.checkpoint.lastOutput}}</small><p v-if="j.error" class="fs-analysis-warning">{{j.error.code}}：{{j.error.message}}</p></div><div><WorkbenchProgress :value="j.progress" :max="1" :label="labels[j.type]+'进度'"/><small>{{Math.round(j.progress*100)}}%</small><button v-if="j.retry&&(failed(j)||!!j.retry.resumeId)" class="secondary-button" @click="emit('retry',j)">重新关联并重试</button></div></article></section></section>
 <div class="fs-jobs-utilities"> <section class="fs-analysis fs-batch"><h3>批量媒体处理</h3><p v-if="recoveredBatch&&!batchBusy" class="fs-analysis-disclaimer">保留上次批次参数及结果；恢复时按原顺序重新选择所有文件，已建立检查点的项目验证原目录及完整内容，未启动项使用新授权目录。<button class="secondary-button" @click="discardBatch">清除批次历史</button><button v-if="recoveredBatch.sessions?.some(Boolean)" class="secondary-button" @click="confirmCleanup=true">删除批次检查点（保留文件）</button><button class="secondary-button" @click="refreshPermissions">检查目录权限</button></p><div v-if="recoveredBatch&&!batchBusy" v-for="(id,i) in recoveredBatch.sessions??[]" :key="id||i"><template v-if="id"><small>{{recoveredBatch.files[i]?.name}} · {{permissionRows[id]??'未检查'}}</small><button v-if="permissionRows[id]!=='granted'&&permissionRows[id]!=='missing'" type="button" class="secondary-button" @click="reauthorize(id)">重新授权该目录</button></template></div><p class="fs-analysis-disclaimer">最多 50 个视频，按顺序处理。</p><div class="fs-center-toolbar"><label class="secondary-button">选择视频<input type="file" multiple accept="video/*,.mp4,.mov,.mkv,.webm" aria-label="批量媒体文件" :disabled="batchBusy" @change="selectBatch"/></label><span>{{batchFiles.length}} 个文件</span><WorkbenchSelect v-model="batchMode" label="批处理方式" :disabled="batchBusy" :options="([{value:'split',label:'无损分割'},{value:'frames',label:'定时抽帧'}] as const)"/><label v-if="batchMode==='split'">大小 GB <input v-model.number="batchSize" type="number" min=".032" step=".1" :disabled="batchBusy"/></label><label v-else>间隔秒 <input v-model.number="batchInterval" type="number" min=".1" :disabled="batchBusy"/></label><button v-if="!batchBusy" class="secondary-button" :disabled="!batchFiles.length" @click="startBatch(false)">选择目录并开始批处理</button><button v-else class="secondary-button" @click="batchController?.abort()">取消批处理</button><button v-if="!batchBusy&&recoveredBatch?.sessions?.some(Boolean)" class="secondary-button" :disabled="!batchFiles.length" @click="startBatch(true)">验证并恢复批次</button><div class="fs-inline-field"><span>优先级</span><WorkbenchSelect v-model="batchPriority" label="批处理优先级" :disabled="batchBusy" :options="([{value:'background',label:'后台'},{value:'normal',label:'普通'},{value:'high',label:'高'}] as const)"/></div></div><p v-if="batchError" class="fs-analysis-warning">{{batchError}}</p><div v-for="(row,i) in batchRows" :key="i" class="fs-job-row"><strong>{{row.name}} · {{row.status}}</strong><small>{{row.detail}}</small></div></section>
 <StorageDiagnostics :busy="batchBusy||jobs.some(active)" @clear-history="emit('clear')"/>
</div>
 </div></template>
